"use strict";(globalThis.webpackChunkanime_artist_docs=globalThis.webpackChunkanime_artist_docs||[]).push([[804],{7272(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"category","label":"Features & Modules","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/anime_doc/docs/features/overview","label":"Platform Overview","docId":"features/overview","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/architecture","label":"Architecture & Modules","docId":"features/architecture","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/onboarding-authentication","label":"Onboarding & Authentication","docId":"features/onboarding-authentication","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/home-and-discovery","label":"Home & Discovery","docId":"features/home-and-discovery","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/social-and-profiles","label":"Social & Profiles","docId":"features/social-and-profiles","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/commissions","label":"Commissions (Create Post)","docId":"features/commissions","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/services-and-bookings","label":"Services & Bookings","docId":"features/services-and-bookings","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/messaging","label":"Real-time Messaging","docId":"features/messaging","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/artist-studio","label":"Artist Studio & Earnings","docId":"features/artist-studio","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/device-iot","label":"IoT Device Companion","docId":"features/device-iot","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/settings-and-support","label":"Settings & Support","docId":"features/settings-and-support","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/admin-panel","label":"Admin Panel","docId":"features/admin-panel","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/technical-highlights","label":"Technical Highlights","docId":"features/technical-highlights","unlisted":false},{"type":"link","href":"/anime_doc/docs/features/roadmap","label":"Future-Ready Capabilities","docId":"features/roadmap","unlisted":false}],"href":"/anime_doc/docs/category/features--modules"}]},"docs":{"features/admin-panel":{"id":"features/admin-panel","title":"Admin Panel & Backend Operations","description":"The mobile app is powered by a Laravel admin panel + REST API at admin.hype-muse.com. The admin is where operators run the business \u2014 moderating content, approving artists, paying out earnings, configuring payments, and controlling the app remotely.","sidebar":"tutorialSidebar"},"features/architecture":{"id":"features/architecture","title":"Architecture & Module Breakdown","description":"This page is the technical map of the app: how the code is organized, how data flows, how the user moves between screens, and what each role is allowed to do. It is written for engineers onboarding to the codebase and for technical buyers evaluating quality.","sidebar":"tutorialSidebar"},"features/artist-studio":{"id":"features/artist-studio","title":"Artist Studio, Jobs & Earnings","description":"The Artist Studio is the supply side of the marketplace \u2014 the toolset a verified creator uses to win work, deliver it, and get paid. It is gated behind an admin-approved verification flow, so quality stays high.","sidebar":"tutorialSidebar"},"features/commissions":{"id":"features/commissions","title":"Commissions \u2014 The Reverse Marketplace","description":"Most marketplaces only let sellers list. This platform also lets fans post a brief and have artists come to them \u2014 an Upwork-style reverse marketplace. A fan describes the artwork they want, sets a budget and deadline, and either broadcasts it or invites a specific artist.","sidebar":"tutorialSidebar"},"features/device-iot":{"id":"features/device-iot","title":"IoT Device Companion (Smart-watch)","description":"The Device tab is the platform\'s hardware differentiator: it turns fans\' artwork into a wearable. Users connect a Bluetooth smart-watch (a JieLi-chipset device) and push a custom image straight to the watch face \u2014 taking digital art off the screen and onto a physical display.","sidebar":"tutorialSidebar"},"features/home-and-discovery":{"id":"features/home-and-discovery","title":"Home & Discovery","description":"Discovery is how fans find artists and work. It spans four surfaces \u2014 Home, Explore, Search, and Trend/Rank \u2014 each tuned for a different intent.","sidebar":"tutorialSidebar"},"features/messaging":{"id":"features/messaging","title":"Real-time Messaging","description":"Commission work needs conversation \u2014 reference sharing, revisions, and dispute resolution. The platform ships a full real-time 1-to-1 chat built on Laravel Reverb (Pusher protocol) over native Dart WebSockets, not polling.","sidebar":"tutorialSidebar"},"features/onboarding-authentication":{"id":"features/onboarding-authentication","title":"Onboarding & Authentication","description":"This module covers everything from first launch to a signed-in session: the bootstrap splash, the intro carousel, the four sign-in methods, OTP verification, profile completion, password recovery, and the security center.","sidebar":"tutorialSidebar"},"features/overview":{"id":"features/overview","title":"Platform Overview & Feature Matrix","description":"Hypemuse is a hybrid mobile application that fuses four proven business models into a single, vertically-integrated product for the anime art community:","sidebar":"tutorialSidebar"},"features/roadmap":{"id":"features/roadmap","title":"Future-Ready Capabilities & Roadmap","description":"Beyond what ships today, the codebase is deliberately structured for expansion. Several capabilities are already scaffolded in the architecture and can be activated without re-architecting. This page is useful for buyers evaluating longevity and for teams planning the next release.","sidebar":"tutorialSidebar"},"features/services-and-bookings":{"id":"features/services-and-bookings","title":"Services, Bookings & Payments","description":"This is the forward marketplace: artists list services, fans browse, book, pay, track the order, and leave reviews. It is the primary revenue surface of the platform.","sidebar":"tutorialSidebar"},"features/settings-and-support":{"id":"features/settings-and-support","title":"Settings, Localization & Support","description":"The settings module is the user\'s control center and the platform\'s compliance surface \u2014 preferences, localization, notifications, support, and all legal content.","sidebar":"tutorialSidebar"},"features/social-and-profiles":{"id":"features/social-and-profiles","title":"Social, Profiles & Engagement","description":"The social layer turns the marketplace into a community: profiles, portfolios, follows, post engagement, invitations, and a personal QR identity.","sidebar":"tutorialSidebar"},"features/technical-highlights":{"id":"features/technical-highlights","title":"Technical Highlights & Platform Systems","description":"This page collects the engineering decisions and cross-cutting systems that make the app production-grade \u2014 the things a technical reviewer or buyer\'s developer will care about.","sidebar":"tutorialSidebar"}}}}')}}]);